{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{{ header("DELIVERY NOTE", "إشعار تسليم", doc.name, doc.posting_date, doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Deliver to · التسليم إلى</div><b>{{ doc.customer_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Dispatch · الشحن</div>Driver / vehicle: {{ doc.driver_name or "—" }} {{ doc.vehicle_no or "" }}<br>Customer PO: {{ doc.po_no or "—" }}<br>Status: {{ doc.status }}</div></div>
<table class="hs-t"><thead><tr><th>#</th><th>Description · الوصف</th><th class="n">Qty · الكمية</th><th>Unit</th><th>From warehouse</th></tr></thead><tbody>{% for i in doc.items %}<tr><td>{{ loop.index }}</td><td>{{ i.item_name }}{% set ar = hs_arabic_name(i.item_code) %}{% if ar %}<span class="ar-sub">{{ ar }}</span>{% endif %}{% set sn = hs_serials(i) %}{% if sn %}<span class="ar-sub" dir="ltr">S/N {{ sn }}{% set wm = hs_warranty_months(i.item_code) %}{% if wm %} · warranty {{ wm }} months{% endif %}</span>{% endif %}</td><td class="n">{{ i.get_formatted("qty") }}</td><td>{{ i.uom }}</td><td>{{ i.warehouse }}</td></tr>{% endfor %}</tbody></table>
{% if doc.hs_pod_signature %}<div class="hs-two" style="margin-top:18px"><div><div class="hs-h4">Delivered by · سلّمها</div>{{ doc.hs_driver or doc.driver_name or "" }}<br>{{ frappe.format(doc.hs_pod_time, {"fieldtype": "Datetime"}) if doc.hs_pod_time else "" }}{% if doc.hs_pod_gps %}<br>GPS {{ doc.hs_pod_gps }}{% endif %}</div><div><div class="hs-h4">Received by · المستلم</div><b>{{ doc.hs_received_by }}</b><br><img src="{{ doc.hs_pod_signature }}" style="max-height:70px;max-width:220px"></div></div>{% else %}{{ signs("Delivered by", "Received in good condition — name, signature & date") }}{% endif %}
</div>
